// التحقق من توقيع مِحوَر (HMAC-SHA256 على `${timestamp}.${body}`) — يتطلّب NODE_FUNCTION_ALLOW_BUILTIN=crypto
const crypto = require('crypto');
const item = $input.first().json;
const ts = item.headers['x-mihwar-timestamp'];
const sig = item.headers['x-mihwar-signature'];
const body = JSON.stringify(item.body);
const expected = crypto.createHmac('sha256', $env.MIHWAR_SHARED_SECRET).update(`${ts}.${body}`).digest('hex');
if (!sig || sig !== expected) throw new Error('توقيع غير صالح');
if (Math.abs(Date.now() - Number(ts)) > 10 * 60 * 1000) throw new Error('طابع زمني منتهٍ');
return [{ json: item.body }];

// التعليمات حسب نوع المخرج — حزمة المصادر تحمل المقرر ومستواه ومخرجات الموضوع ومرجعه.
const j = $input.first().json;
const base = j.sourcePack;
const byKind = {
  TEXT: 'اكتب شرحًا نصيًا منظّمًا بعناوين فرعية لهذا الموضوع (٨٠٠–١٢٠٠ كلمة)، بالعربية الفصحى المبسّطة، ثم ثلاثة أسئلة مراجعة.',
  SLIDES: 'أعدّ مخطط عرض تقديمي من ١٠–١٤ شريحة: لكل شريحة عنوان وثلاث إلى خمس نقاط وملاحظة للمتحدّث. أعد JSON فقط: [{"title":"","bullets":[],"notes":""}]',
  AUDIO: 'اكتب نص حوار بودكاست تعليمي بين «المقدّم» و«الضيف» (٦–٨ دقائق) يشرح الموضوع بأسلوب شيّق. كل سطر يبدأ بـ «المقدّم:» أو «الضيف:».',
  VIDEO: 'اكتب وصفًا بصريًا لفيديو تعليمي قصير (٨ ثوانٍ) يوضّح الفكرة المحورية لهذا الموضوع، بالإنجليزية، دون نصوص على الشاشة.',
};
return [{ json: { ...j, prompt: `${base}\n\n${byKind[j.kind]}` } }];

// تحويل نص Gemini إلى نتيجة للمنصة
const j = $('Build prompt').first().json;
const text = $input.first().json.candidates?.[0]?.content?.parts?.map(p => p.text).join('') ?? '';
return [{ json: { jobId: j.jobId, tenantId: j.tenantId, status: text ? 'SUCCEEDED' : 'FAILED', error: text ? undefined : 'رد فارغ من النموذج', result: { title: `${j.kindLabel}: ${j.topicTitle}`, text } } }];

// يحفظ الصوت (PCM 24kHz) ويحوّله mp3 بـ ffmpeg ثم يرفعه لرابط R2 المؤقت. يتطلّب n8n مستضافًا ذاتيًا فيه ffmpeg
// و NODE_FUNCTION_ALLOW_BUILTIN=child_process,fs,crypto
const fs = require('fs'); const { execSync } = require('child_process');
const j = $('Build prompt').first().json;
const pcm = Buffer.from($input.first().json.candidates[0].content.parts[0].inlineData.data, 'base64');
const dir = `/tmp/${j.jobId}`; fs.mkdirSync(dir, { recursive: true });
fs.writeFileSync(`${dir}/a.pcm`, pcm);
execSync(`ffmpeg -y -f s16le -ar 24000 -ac 1 -i ${dir}/a.pcm -b:a 96k ${dir}/a.mp3`);
const mp3 = fs.readFileSync(`${dir}/a.mp3`);
const res = await fetch(j.upload.url, { method: 'PUT', headers: { 'Content-Type': j.upload.contentType }, body: mp3 });
if (!res.ok) throw new Error('فشل الرفع إلى R2');
return [{ json: { jobId: j.jobId, tenantId: j.tenantId, status: 'SUCCEEDED', result: { title: `بودكاست: ${j.topicTitle}`, objectKey: j.upload.objectKey, sizeBytes: mp3.length, mimeType: 'audio/mpeg' } } }];

// Veo عبر Gemini API: عملية طويلة ← انتظار ← تنزيل ← رفع إلى R2. لا يمرّ الفيديو عبر خادم المنصة.
const j = $('Build prompt').first().json;
const prompt = $input.first().json.candidates[0].content.parts.map(p => p.text).join('');
const base = 'https://generativelanguage.googleapis.com/v1beta';
const key = $env.GEMINI_API_KEY;
let op = await (await fetch(`${base}/models/${$env.VEO_MODEL}:predictLongRunning?key=${key}`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ instances: [{ prompt }], parameters: { aspectRatio: '16:9' } }) })).json();
for (let i = 0; i < 60 && !op.done; i++) { await new Promise(r => setTimeout(r, 10000)); op = await (await fetch(`${base}/${op.name}?key=${key}`)).json(); }
const uri = op.response?.generateVideoResponse?.generatedSamples?.[0]?.video?.uri;
if (!uri) return [{ json: { jobId: j.jobId, tenantId: j.tenantId, status: 'FAILED', error: 'لم يُولَّد الفيديو' } }];
const video = Buffer.from(await (await fetch(`${uri}&key=${key}`)).arrayBuffer());
const up = await fetch(j.upload.url, { method: 'PUT', headers: { 'Content-Type': 'video/mp4' }, body: video });
if (!up.ok) throw new Error('فشل الرفع إلى R2');
return [{ json: { jobId: j.jobId, tenantId: j.tenantId, status: 'SUCCEEDED', result: { title: `فيديو: ${j.topicTitle}`, objectKey: j.upload.objectKey, sizeBytes: video.length, mimeType: 'video/mp4' } } }];

// توقيع النتيجة قبل إرسالها للمنصة
const crypto = require('crypto');
const body = JSON.stringify($input.first().json);
const ts = String(Date.now());
const sig = crypto.createHmac('sha256', $env.MIHWAR_SHARED_SECRET).update(`${ts}.${body}`).digest('hex');
return [{ json: { body, ts, sig, callbackUrl: $('Build prompt').first().json.callbackUrl } }];
